RX = [
 ("^(\\d+) item\\(s\\) waiting for a connection\\.$", "function(m,n){return 'Vipengee '+n+' vinasubiri muunganisho.'}"),
 ("^(\\d+) min read$", "function(m,n){return 'Dakika '+n+' za kusoma'}"),
 ("^Read: (.+)$", "function(m,t){return 'Soma: '+(SW_DICT[t]||t)}"),
 ("^(.+) \\((\\d+) min\\)$", "function(m,t,n){return (SW_DICT[t]||t)+' (dak '+n+')'}"),
 ("^Version ([\\d.]+), protocol (\\S+)\\. Data already sent cannot be linked back to you\\.$", "function(m,v,p){return 'Toleo '+v+', itifaki '+p+'. Data iliyokwisha tumwa haiwezi kuunganishwa tena nawe.'}"),
 ("^Question (\\d+) of (\\d+)$", "function(m,a,b){return 'Swali '+a+' kati ya '+b}"),
 ("^Section (\\d+) of (\\d+)$", "function(m,a,b){return 'Sehemu '+a+' kati ya '+b}"),
 ("^Last done (\\d+) days? ago$", "function(m,n){return 'Ilifanyika siku '+n+' zilizopita'}"),
]
